#!/usr/bin/env node
/**
 * Generates src/main/generated/supportKey.ts from the ROKAR_SUPPORT_KEY secret.
 *
 * WHY THIS EXISTS
 * The Support Recovery HMAC key must never sit in a source file that lives in a
 * PUBLIC git repository — anyone could then mint a valid recovery code for any
 * shop and unlock their POS without the developer's involvement. The key lives
 * in .env (gitignored) and is injected into the build by this script.
 *
 * The generated file is gitignored too, so `git add -A` can never stage it.
 *
 * FAIL-SAFE: with no key in .env the generated file exports an empty string and
 * the app compiles and runs with Support Recovery DISABLED (the UI explains
 * why). Option A (security question / recovery code) does not use this key and
 * keeps working. A broken/absent build secret must never break the whole app.
 */
const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.resolve(__dirname, '..');
const ENV_FILE = path.join(ROOT, '.env');
const OUT_FILE = path.join(ROOT, 'src', 'main', 'generated', 'supportKey.ts');

/** Minimal .env reader — avoids a dotenv dependency in a build-time script. */
function readEnvFile(file) {
  const out = {};
  if (!fs.existsSync(file)) return out;
  for (const rawLine of fs.readFileSync(file, 'utf8').split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;
    const eq = line.indexOf('=');
    if (eq === -1) continue;
    const key = line.slice(0, eq).trim();
    let value = line.slice(eq + 1).trim();
    if (
      (value.startsWith('"') && value.endsWith('"') && value.length > 1) ||
      (value.startsWith("'") && value.endsWith("'") && value.length > 1)
    ) {
      value = value.slice(1, -1);
    }
    out[key] = value;
  }
  return out;
}

function main() {
  // An explicit environment variable wins, so CI can inject without a .env file.
  const raw =
    process.env.ROKAR_SUPPORT_KEY ||
    readEnvFile(ENV_FILE).ROKAR_SUPPORT_KEY ||
    '';

  const hex = raw.trim().toLowerCase();
  const valid = /^[0-9a-f]{64}$/.test(hex);

  if (hex && !valid) {
    console.error(
      '[gen-support-key] ROKAR_SUPPORT_KEY is present but is not 64 hex characters.\n' +
        `  got: ${JSON.stringify(hex.slice(0, 24))}${hex.length > 24 ? '...' : ''} (length ${hex.length})\n` +
        '  Support Recovery will stay DISABLED. Generate a valid one with:\n' +
        '    node -e "console.log(require(\'crypto\').randomBytes(32).toString(\'hex\'))"',
    );
  }

  const body = `
/**
 * AUTO-GENERATED by scripts/gen-support-key.js — DO NOT EDIT, DO NOT COMMIT.
 *
 * This file is gitignored. It exists only in your local build tree.
 * Source of truth: ROKAR_SUPPORT_KEY in .env
 *
 * When SUPPORT_KEY_HEX is empty, Support Recovery (Option B) is disabled.
 * Option A (security question / owner recovery code) is unaffected.
 */
// GENERATED FILE — regenerated on every build. Not part of the repository.
export const SUPPORT_KEY_HEX = '${valid ? hex : ''}';
`.trimStart();

  fs.mkdirSync(path.dirname(OUT_FILE), { recursive: true });
  fs.writeFileSync(OUT_FILE, body, 'utf8');

  if (valid) {
    console.log('[gen-support-key] Support Recovery key injected (64 hex chars).');
  } else {
    console.warn(
      '[gen-support-key] WARNING: no ROKAR_SUPPORT_KEY in .env — Support Recovery (Option B) is DISABLED.',
    );
  }
}

main();
